const page: CSSProperties = {height: '100dvh'};
const columnRow: CSSProperties = {overflowX: 'auto', overflowY: 'hidden'};
const scrollable: CSSProperties = {overflowY: 'auto'};
const fixedColumn: CSSProperties = {flexShrink: 0};
const detailColumn: CSSProperties = {
  flexGrow: 1,
  flexShrink: 0,
  flexBasis: 320,
};

function findItem(items: FileSystemItem[], id: string): FileSystemItem | null {
  for (const item of items) {
    if (item.id === id) {
      return item;
    }
    if (item.children) {
      const found = findItem(item.children, id);
      if (found) {
        return found;
      }
    }
  }
  return null;
}

function getFileExtension(name: string): string {
  const dot = name.lastIndexOf('.');
  return dot > 0 ? name.substring(dot + 1).toUpperCase() : 'File';
}

export default function FileExplorerPage() {
  const [selectedPath, setSelectedPath] = useState<string[]>([
    'applications',
    'chrome-apps',
    'component-lab',
  ]);

  const columns = useMemo(() => {
    const cols: {items: FileSystemItem[]; selectedId: string | null}[] = [];
    cols.push({items: FILESYSTEM, selectedId: selectedPath[0] ?? null});
    let currentItems: FileSystemItem[] = FILESYSTEM;
    for (let i = 0; i < selectedPath.length; i++) {
      const selected = currentItems.find(item => item.id === selectedPath[i]);
      if (selected?.children && selected.children.length > 0) {
        cols.push({
          items: selected.children,
          selectedId: selectedPath[i + 1] ?? null,
        });
        currentItems = selected.children;
      } else {
        break;
      }
    }
    return cols;
  }, [selectedPath]);

  const currentFolderName = useMemo(() => {
    if (selectedPath.length === 0) {
      return 'Home';
    }
    const lastId = selectedPath[selectedPath.length - 1];
    const item = findItem(FILESYSTEM, lastId);
    if (item?.type === 'folder') {
      return item.name;
    }
    if (selectedPath.length >= 2) {
      const parent = findItem(
        FILESYSTEM,
        selectedPath[selectedPath.length - 2],
      );
      return parent?.name ?? 'Home';
    }
    return 'Home';
  }, [selectedPath]);

  const selectedFile = useMemo(() => {
    if (selectedPath.length === 0) {
      return null;
    }
    const lastId = selectedPath[selectedPath.length - 1];
    const item = findItem(FILESYSTEM, lastId);
    return item?.type === 'file' ? item : null;
  }, [selectedPath]);

  const handleSelect = (columnIndex: number, itemId: string) => {
    setSelectedPath([...selectedPath.slice(0, columnIndex), itemId]);
  };

  return (
    <Layout
      style={page}
      height="fill"
      header={
        <Toolbar
          label="File Explorer"
          size="sm"
          dividers={['bottom']}
          startContent={
            <>
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={ChevronLeftIcon} size="sm" />}
                onClick={() => {
                  if (selectedPath.length > 0) {
                    setSelectedPath(selectedPath.slice(0, -1));
                  }
                }}
                isDisabled={selectedPath.length === 0}
                label="Go back"
              />
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={ChevronRightIcon} size="sm" />}
                isDisabled
                label="Go forward"
              />
              <Text type="label">{currentFolderName}</Text>
            </>
          }
          centerContent={
            <SegmentedControl
              value="column"
              onChange={() => {}}
              label="View mode">
              <SegmentedControlItem
                value="grid"
                label="Grid"
                icon={<Icon icon={Squares2X2Icon} size="sm" />}
                isLabelHidden
              />
              <SegmentedControlItem
                value="list"
                label="List"
                icon={<Icon icon={Bars4Icon} size="sm" />}
                isLabelHidden
              />
              <SegmentedControlItem
                value="column"
                label="Column"
                icon={<Icon icon={ViewColumnsIcon} size="sm" />}
                isLabelHidden
              />
              <SegmentedControlItem
                value="gallery"
                label="Gallery"
                icon={<Icon icon={TableCellsIcon} size="sm" />}
                isLabelHidden
              />
            </SegmentedControl>
          }
          endContent={
            <>
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={AdjustmentsHorizontalIcon} size="sm" />}
                label="Group"
              />
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={ShareIcon} size="sm" />}
                label="Share"
              />
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={TagIcon} size="sm" />}
                label="Tags"
              />
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={EllipsisHorizontalIcon} size="sm" />}
                label="More"
              />
              <IconButton
                variant="ghost"
                size="sm"
                icon={<Icon icon={MagnifyingGlassIcon} size="sm" />}
                label="Search"
              />
            </>
          }
        />
      }
      content={
        <LayoutContent padding={0} isScrollable={false}>
          <HStack height="100%" style={columnRow}>
            {columns.map((col, colIndex) => {
              const showDivider =
                colIndex < columns.length - 1 || selectedFile != null;
              return (
                <Section
                  key={colIndex}
                  width={240}
                  padding={2}
                  variant="transparent"
                  dividers={showDivider ? ['end'] : undefined}
                  style={{...scrollable, ...fixedColumn}}>
                  <List density="compact" hasDividers={false}>
                    {col.items.map(item => {
                      const isSelected = col.selectedId === item.id;
                      const hasChildren =
                        item.type === 'folder' &&
                        item.children != null &&
                        item.children.length > 0;
                      return (
                        <ListItem
                          key={item.id}
                          label={item.name}
                          startContent={
                            <Icon
                              icon={
                                item.type === 'folder'
                                  ? FolderIcon
                                  : DocumentIcon
                              }
                              color={
                                item.type === 'folder' ? 'accent' : 'secondary'
                              }
                              size="sm"
                            />
                          }
                          endContent={
                            hasChildren ? (
                              <Icon
                                icon={ChevronRightIcon}
                                size="xsm"
                                color="secondary"
                              />
                            ) : undefined
                          }
                          onClick={() => handleSelect(colIndex, item.id)}
                          isSelected={isSelected}
                        />
                      );
                    })}
                  </List>
                </Section>
              );
            })}
            {selectedFile && (
              <Section
                padding={6}
                variant="transparent"
                style={{...scrollable, ...detailColumn}}>
                <VStack gap={4} hAlign="center">
                  <Avatar name={selectedFile.name} size={96} />
                  <VStack gap={1} hAlign="center">
                    <Text type="label">{selectedFile.name}</Text>
                    <Text type="supporting">
                      {getFileExtension(selectedFile.name)} Document
                    </Text>
                  </VStack>
                  <MetadataList title="Information">
                    <MetadataListItem label="Created">
                      March 28, 2026 at 2:15 PM
                    </MetadataListItem>
                    <MetadataListItem label="Modified">
                      Yesterday, 10:27 PM
                    </MetadataListItem>
                    <MetadataListItem label="Kind">
                      {getFileExtension(selectedFile.name)} Document
                    </MetadataListItem>
                  </MetadataList>
                </VStack>
              </Section>
            )}
          </HStack>
        </LayoutContent>
      }
    />
  );
}
`,"/templates/table-filter/":`// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * Table page driven by a row of filter selectors.
 *
 * Each filterable field is a Selector, so the closed trigger doubles as the
 * filter chip: unset it reads as the bare field name against the same outlined
 * chrome as the search box, and once set it fills in and expands to the whole
 * clause (\`Status is Overdue\`) with a clear beside it. Anything the selectors
 * can't express — free numeric comparisons, OR groups — swaps to power search,
 * and because both modes read the same filter array, a filter built either way
 * survives the swap.
 *
 * The same row is where saved views and bulk edit surface: selecting rows
 * replaces it with a selection bar, and the saved-views toggle swaps it for a
 * list of saved views. A saved view is the whole screen — the filters plus the
 * columns, density, sticky edges and grouping — so applying one restores the
 * table as it was, and there is no separate column preset to disagree with it.
 *
 * Clicking a row opens its details in the end panel. That is separate from the
 * checkbox selection driving bulk edit — a row can be open without being
 * selected, and vice versa.
 *
 * @input Deterministic fixtures only (field-service jobs for a mechanical
 *   contractor: customers, technicians, fixed ISO schedule times, quotes)
 */

import {useCallback, useEffect, useId, useMemo, useRef, useState} from 'react';
