type Density = 'compact' | 'balanced' | 'spacious';
type StickyEdge = 'none' | 'one' | 'two';
/** Field the rows section under. 'none' leaves the table flat. */
type GroupField = 'none' | 'status' | 'priority' | 'technician' | 'customer';

