`,"/templates/InternationalizationProvider03RtlDirection/":`// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

import {useState} from 'react';
import {InternationalizationProvider} from '@astryxdesign/core/i18n';
import {VStack} from '@astryxdesign/core/Layout';
import {Pagination} from '@astryxdesign/core/Pagination';
import {
  SegmentedControl,
  SegmentedControlItem,
} from '@astryxdesign/core/SegmentedControl';

type TextDirection = 'ltr' | 'rtl';

export default function InternationalizationProviderRtlDirection() {
  const [textDirection, setTextDirection] = useState<TextDirection>('ltr');
  const [page, setPage] = useState(3);
  return (
    <InternationalizationProvider locale="en" dir={textDirection}>
      {/* \`dir\` on the VStack scopes text direction to this subtree — no extra
          wrapper needed. (VStack has no \`direction\` prop, so there's nothing to
          confuse with \`dir\` here.) */}
      <VStack
        gap={4}
        hAlign="center"
        dir={textDirection}
        style={{width: '100%'}}>
        <SegmentedControl
          label="Direction"
          value={textDirection}
          onChange={next => setTextDirection(next as TextDirection)}
          size="sm">
          <SegmentedControlItem value="ltr" label="LTR" />
          <SegmentedControlItem value="rtl" label="RTL" />
        </SegmentedControl>
        <Pagination
          page={page}
          onChange={setPage}
          totalItems={200}
          pageSize={10}
          variant="pages"
        />
      </VStack>
    </InternationalizationProvider>
  );
}
`,"/templates/InternationalizationProvider01ShippedLocale/":`// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

import {useState} from 'react';
import {InternationalizationProvider} from '@astryxdesign/core/i18n';
import frFR from '@astryxdesign/core/locales/fr-FR.json';
import {Stack} from '@astryxdesign/core/Layout';
import {
  SegmentedControl,
  SegmentedControlItem,
} from '@astryxdesign/core/SegmentedControl';
import {Selector} from '@astryxdesign/core/Selector';

type Locale = 'en' | 'fr-FR';

export default function InternationalizationProviderShippedLocale() {
  const [locale, setLocale] = useState<Locale>('en');
  const [value, setValue] = useState<string | null>(null);
  return (
    <InternationalizationProvider locale={locale} messages={{'fr-FR': frFR}}>
      <Stack direction="vertical" gap={4} hAlign="center">
        <SegmentedControl
          label="Language"
          value={locale}
          onChange={nextLocale => setLocale(nextLocale as Locale)}
          size="sm">
          <SegmentedControlItem value="en" label="EN" />
          <SegmentedControlItem value="fr-FR" label="FR" />
        </SegmentedControl>
        <Selector
          style={{width: 300}}
          label="Billing region"
          options={[
            {value: 'americas', label: 'Americas'},
            {value: 'emea', label: 'EMEA'},
            {value: 'apac', label: 'APAC'},
          ]}
          value={value}
          onChange={setValue}
          hasClear
        />
      </Stack>
    </InternationalizationProvider>
  );
}
